<?php
// ---------- Custom SCF variables global ----------
if (function_exists('acf_add_options_page')) {
	acf_add_options_page([
		'page_title' => 'Global Variables',
		'menu_title' => 'Global Variables',
		'menu_slug' => 'puramu-global-variables',
		'capability' => 'manage_options',
		'icon_url' => 'data:image/svg+xml;base64,',
		'redirect' => false
	]);
}

// ---------- Register Nav Menu ----------
register_nav_menus(
	[
		'primary' => __('Primary Menu', 'tailpress'),
		'top-nav' => __('Top Nav Menu', 'tailpress'),
		'footer' => __('Footer Menu', 'tailpress'),
	]
);

// ---------- Add Menu ----------
function add_menu()
{
	add_theme_support('menus');
	register_nav_menu('themeLocationOne', 'Theme Footer One');
	register_nav_menu('themeLocationTwo', 'Theme Footer Two');
}
add_action('after_setup_theme', 'add_menu');

// Enable WooCommerce
function enable_woocommerce()
{
    add_theme_support('woocommerce');
}
add_action('after_setup_theme', 'enable_woocommerce');

// ---------- Custom Shortcode ----------
function ten_function_cua_ban() {
	ob_start();
	?>
	<div class="container">
		<h1>Hello World</h1>
	</div>
	<?php
	return ob_get_clean();
}
add_action( 'hook_name', 'ten_function_cua_ban', 10 );



